

# ==============================================================================
# Compute daily thermal habitat indices from ESA CCI L4 SST NetCDF files
# across multiple spatial polygons (Labrador Sea, Belle Isle Strait, migration
# corridors). One FST cache file is produced per polygon per month.
#
# Inputs:
#   - R/00_raw_data/SST_ORAS5_Labrador/ESACCI_SST_L4_<YYYY>_<MM>.nc
#     Monthly NetCDF files containing daily SST and sea-ice fields.
#     Too large for GitHub — not included in this repository.
#     Generated by running: 00_download_SST_ORAS5_Labrador.R
#
#   - R/00_raw_data/ReferenceMigrationLayers/<polygon>.shp
#     Shapefiles defining spatial polygons for index computation.
#     Included in this repository.
#
# Outputs:
#   - R/01_derived_data/SST_Index/SST_Index_<PolygonName>/TH_<YYYY>_<MM>.fst
#     Daily thermal habitat index per polygon per month (FST format).
#     Too large for GitHub — not included in this repository.
#     Generated by running this script.
# ==============================================================================


library(data.table)
library(fst)
library(terra)
library(sf)
library(lubridate)
library(future.apply)
library(ncdf4)


# ── Working directory ──────────────────────────────────────────────────────
# Automatically detects the repository root based on the script location.
# No hardcoded path — works on any machine.
current_file <- rstudioapi::getActiveDocumentContext()$path
path_parts   <- unlist(strsplit(normalizePath(current_file, winslash = "/"), "/"))
target_index <- which(path_parts == "phd-chapter3-Atlantic-Salmon")
base_path    <- paste(path_parts[1:target_index], collapse = "/")
setwd(base_path)


# ══════════════════════════════════════════════════════════════════════════════
# CONFIGURATION
# ══════════════════════════════════════════════════════════════════════════════

download_dir <- file.path(base_path, "R/00_raw_data/SST_ORAS5_Labrador")       # Input NetCDF directory
output_base  <- file.path(base_path, "R/01_derived_data/SST_Index")            # Root output directory
shp_path_dir <- file.path(base_path, "R/00_raw_data/ReferenceMigrationLayers") # Shapefile directory

# Temporary directory for files extracted from monthly archives
tmp_dir <- file.path(download_dir, "tmp_processing")

# Number of parallel workers for processing daily files within each month
n_workers <- 4

# Minimum valid cache file size (bytes); smaller files are treated as corrupt
min_cache_size <- 1000


# ══════════════════════════════════════════════════════════════════════════════
# FUNCTIONS
# ══════════════════════════════════════════════════════════════════════════════

# ── thermal_habitat ───────────────────────────────────────────────────────────
# Purpose: Computes a daily thermal habitat growth index per pixel based on SST,
#   sea-ice concentration, and sea-winter age class, weighted by grid-cell area.
# Parameters:
#   sst      - numeric vector. Sea surface temperature values (degrees Celsius).
#   ice      - numeric vector. Sea ice concentration (0-1 fraction).
#   year_sw  - integer. Sea-winter age class (1 or 2).
#   lon      - numeric vector. Longitude of pixel centers (degrees WGS84).
#   lat      - numeric vector. Latitude of pixel centers (degrees WGS84).
#   res_x    - numeric. Longitudinal cell resolution (degrees).
#   res_y    - numeric. Latitudinal cell resolution (degrees).
# Returns:
#   A list with two elements:
#     growth_weighted - growth index per pixel weighted by cell area (km2).
#     cell_area_km2   - area of each grid cell in km2.

thermal_habitat <- function(sst, ice, year_sw, lon, lat, res_x, res_y) {
  
  # Approximate cell dimensions in meters; longitude scaled by cos(lat)
  dx_m          <- res_x * cos(lat * pi / 180) * 111320
  dy_m          <- res_y * 111320
  cell_area_km2 <- (dx_m * dy_m) / 1e6
  
  # Thermal tolerance parameters differ between 1SW and 2SW fish
  if (year_sw == 1L) {
    t_min <- 1; t_opt1 <- 6; t_opt2 <- 14; t_max <- 18
  } else if (year_sw == 2L) {
    t_min <- 1; t_opt1 <- 6; t_opt2 <- 12; t_max <- 15
  } else stop("year_sw must be 1 or 2")
  
  # Linear slopes for sub-optimal and supra-optimal temperature ranges
  a_low  <- 1 / (t_opt1 - t_min)
  b_low  <- 1 - a_low * t_opt1
  a_high <- 1 / (t_opt2 - t_max)
  b_high <- 1 - a_high * t_opt2
  
  growth    <- numeric(length(sst))
  growth[]  <- NA_real_
  
  # Pixels with >50% ice cover are excluded (not suitable habitat)
  valid <- ice < 0.5 & !is.na(sst)
  
  # Piecewise linear growth function
  growth[valid & sst >= t_opt1 & sst <= t_opt2] <- 1
  growth[valid & sst >= t_min  & sst <  t_opt1] <- a_low  * sst[valid & sst >= t_min  & sst <  t_opt1] + b_low
  growth[valid & sst >  t_opt2 & sst <= t_max]  <- a_high * sst[valid & sst >  t_opt2 & sst <= t_max]  + b_high
  growth[!valid | sst < 1 | sst > t_max]        <- 0
  
  growth_weighted <- growth * cell_area_km2
  
  return(list(growth_weighted = growth_weighted, cell_area_km2 = cell_area_km2))
}


# ── load_standard_shp ─────────────────────────────────────────────────────────
# Purpose: Reads a shapefile, reprojects it to WGS84, validates geometries,
#   and ensures a consistent integer FID column is present.
# Parameters:
#   fname - character. Filename of the shapefile (basename only; path set
#           by shp_path_dir defined in CONFIGURATION).
# Returns:
#   An sf object in EPSG:4326 with a validated integer FID column.

load_standard_shp <- function(fname) {
  shp <- st_read(file.path(shp_path_dir, fname), quiet = TRUE) |>
    st_transform(4326) |>
    st_make_valid()
  if ("name" %in% names(shp)) names(shp)[names(shp) == "name"] <- "FID"
  if (!"FID" %in% names(shp)) shp$FID <- 0L
  shp$FID <- as.integer(shp$FID)
  shp
}


# ── process_day ───────────────────────────────────────────────────────────────
# Purpose: Extracts SST and sea-ice values from a single daily NetCDF file,
#   crops each polygon/FID, and computes thermal habitat indices for both
#   1SW and 2SW age classes.
# Parameters:
#   f_nc            - character. Full path to a daily NetCDF file.
#   poly_meta_local - named list of polygon metadata (as built in MAIN SCRIPT).
# Returns:
#   A named list (one entry per polygon) of data.tables, each with one row per
#   FID containing date, pixel count, TH indices, and SST summary statistics.

process_day <- function(f_nc, poly_meta_local) {
  
  library(terra)
  library(data.table)
  library(ncdf4)
  library(sf)
  library(lubridate)
  
  # Date is encoded in the first 8 characters of the daily filename (YYYYMMDD)
  bname    <- basename(f_nc)
  date_str <- substr(bname, 1, 8)
  date_i   <- tryCatch(as.Date(date_str, format = "%Y%m%d"),
                       error = function(e) NA_Date_)
  if (is.na(date_i)) return(NULL)
  
  # Load all layers once; identify SST and ice-fraction band indices
  r_all <- tryCatch(rast(f_nc), error = function(e) NULL)
  if (is.null(r_all)) return(NULL)
  
  sst_idx <- grep("analysed_sst$", names(r_all), value = FALSE)
  if (length(sst_idx) == 0) sst_idx <- 1L
  r_sst <- r_all[[sst_idx[1]]]
  
  ice_idx <- grep("sea_ice_fraction", names(r_all), value = FALSE)
  has_ice <- length(ice_idx) > 0
  r_ice   <- if (has_ice) r_all[[ice_idx[1]]] else NULL
  
  # terra may not parse the CDS NetCDF extent correctly; override with true
  # coordinate vectors read directly via ncdf4
  nc_tmp  <- nc_open(f_nc)
  lons_nc <- ncvar_get(nc_tmp, "lon")
  lats_nc <- ncvar_get(nc_tmp, "lat")
  nc_close(nc_tmp)
  
  true_ext <- ext(min(lons_nc) - 0.025, max(lons_nc) + 0.025,
                  min(lats_nc) - 0.025, max(lats_nc) + 0.025)
  
  ext(r_sst)  <- true_ext
  crs(r_sst)  <- "EPSG:4326"
  r_sst_c     <- r_sst - 273.15   # Convert Kelvin to Celsius
  
  if (has_ice) {
    ext(r_ice) <- true_ext
    crs(r_ice) <- "EPSG:4326"
  }
  
  # Process each polygon in poly_meta_local
  results <- lapply(poly_meta_local, function(pm) {
    
    rows_poly <- lapply(pm$fid_list, function(fid_item) {
      
      shp_fid <- tryCatch(
        vect(st_as_sf(st_as_sfc(fid_item$wkt, crs = 4326))),
        error = function(e) NULL
      )
      if (is.null(shp_fid)) return(NULL)
      
      # Crop and mask SST raster to this FID geometry
      r_sst_m <- tryCatch(
        mask(crop(r_sst_c, shp_fid), shp_fid),
        error = function(e) NULL
      )
      if (is.null(r_sst_m)) return(NULL)
      
      sst_vals <- values(r_sst_m)[, 1]
      
      # Use ice fraction if available; otherwise assume ice-free
      if (has_ice) {
        r_ice_m  <- tryCatch(
          mask(crop(r_ice, shp_fid), shp_fid),
          error = function(e) NULL
        )
        ice_vals <- if (!is.null(r_ice_m)) {
          v <- values(r_ice_m)[, 1]; v[is.na(v)] <- 0; v
        } else rep(0, length(sst_vals))
      } else {
        ice_vals <- rep(0, length(sst_vals))
      }
      
      # Build per-pixel table; discard pixels with missing SST
      xy    <- xyFromCell(r_sst_m, seq_len(ncell(r_sst_m)))
      dt_px <- data.table(x = xy[, 1], y = xy[, 2],
                          sst = sst_vals, ice_frac = ice_vals)
      dt_px <- dt_px[!is.na(sst)]
      if (nrow(dt_px) == 0) return(NULL)
      
      # Thermal habitat index for both age classes; area-weighting accounts
      # for Earth curvature via cos(lat) inside thermal_habitat()
      res_1sw <- tryCatch(
        thermal_habitat(sst = dt_px$sst, ice = dt_px$ice_frac, year_sw = 1L,
                        lon = dt_px$x, lat = dt_px$y, res_x = 0.05, res_y = 0.05),
        error = function(e) NULL
      )
      res_2sw <- tryCatch(
        thermal_habitat(sst = dt_px$sst, ice = dt_px$ice_frac, year_sw = 2L,
                        lon = dt_px$x, lat = dt_px$y, res_x = 0.05, res_y = 0.05),
        error = function(e) NULL
      )
      
      data.table(
        date        = date_i,
        year        = year(date_i),
        month       = month(date_i),
        doy         = yday(date_i),
        FID         = as.character(fid_item$fid),
        n_pixels    = nrow(dt_px),
        TH_1SW_sum  = if (!is.null(res_1sw)) sum(res_1sw$growth_weighted,  na.rm = TRUE) else NA_real_,
        TH_1SW_mean = if (!is.null(res_1sw)) mean(res_1sw$growth_weighted, na.rm = TRUE) else NA_real_,
        TH_2SW_sum  = if (!is.null(res_2sw)) sum(res_2sw$growth_weighted,  na.rm = TRUE) else NA_real_,
        TH_2SW_mean = if (!is.null(res_2sw)) mean(res_2sw$growth_weighted, na.rm = TRUE) else NA_real_,
        sst_mean    = mean(dt_px$sst,            na.rm = TRUE),
        sst_median  = median(dt_px$sst,          na.rm = TRUE),
        sst_sd      = sd(dt_px$sst,              na.rm = TRUE),
        sst_min     = min(dt_px$sst,             na.rm = TRUE),
        sst_max     = max(dt_px$sst,             na.rm = TRUE),
        ice_mean    = mean(ice_vals[!is.na(sst_vals)], na.rm = TRUE)
      )
    })
    
    rbindlist(rows_poly, fill = TRUE)
  })
  
  results
}


# ══════════════════════════════════════════════════════════════════════════════
# MAIN SCRIPT
# ══════════════════════════════════════════════════════════════════════════════

# ── Initialize output directories ────────────────────────────────────────────

if (!dir.exists(output_base)) dir.create(output_base, recursive = TRUE)
if (!dir.exists(tmp_dir))     dir.create(tmp_dir, recursive = TRUE)


# ── Load shapefiles and define target polygons ────────────────────────────────

# Named vector mapping polygon labels to their shapefile basenames
shape_files_standard <- c(
  LabradorSea      = "LabradorSea.shp",
  LabradorEntrance = "LabradorSeaEntrance.shp",
  BelleIsle        = "BelleIsleStrait.shp",
  TriniteCorridor  = "TriniteMigrationCorridor_Parts.shp",
  StJeanCorridor   = "StJeanMigrationCorridor_Parts.shp"
)

all_polygons <- lapply(shape_files_standard, load_standard_shp)


# ── Pre-compute polygon metadata ──────────────────────────────────────────────

# For each polygon, store the output directory, per-FID WKT geometry, and
# whether FID is character-typed (needed to restore original type after rbind).
# Using WKT strings allows geometries to be passed safely to parallel workers.

poly_meta <- lapply(names(all_polygons), function(pname) {
  shp     <- all_polygons[[pname]]
  out_dir <- file.path(output_base, paste0("SST_Index_", pname))
  if (!dir.exists(out_dir)) dir.create(out_dir, recursive = TRUE)
  
  fid_list <- lapply(seq_len(nrow(shp)), function(i) {
    list(
      fid = shp$FID[i],
      wkt = st_as_text(st_geometry(shp[i, ]))
    )
  })
  
  list(
    name        = pname,
    out_dir     = out_dir,
    fid_list    = fid_list,
    fid_is_char = is.character(shp$FID)
  )
})
names(poly_meta) <- names(all_polygons)


# ── List available monthly NetCDF files ───────────────────────────────────────

zip_files <- list.files(download_dir,
                        pattern  = "ESACCI_SST_L4_\\d{4}_\\d{2}\\.nc$",
                        full.names = TRUE)
if (length(zip_files) == 0) stop("No ESACCI ZIP files found.")

dt_zips <- data.table(path = zip_files, fname = basename(zip_files))
dt_zips[, year  := as.integer(sub("ESACCI_SST_L4_(\\d{4})_(\\d{2})\\.nc", "\\1", fname))]
dt_zips[, month := as.integer(sub("ESACCI_SST_L4_(\\d{4})_(\\d{2})\\.nc", "\\2", fname))]
setorder(dt_zips, year, month)

message("ZIP files: ", nrow(dt_zips),
        " (", min(dt_zips$year), "-01 to ",
        max(dt_zips$year), "-12)")


# ── Main loop: month -> days (parallel) -> polygons ───────────────────────────

plan(multisession, workers = n_workers)

for (iz in seq_len(nrow(dt_zips))) {
  
  yr    <- dt_zips$year[iz]
  mo    <- dt_zips$month[iz]
  zpath <- dt_zips$path[iz]
  
  # Skip months where all polygon cache files are already present and valid
  all_cached <- all(sapply(names(poly_meta), function(pname) {
    f <- file.path(poly_meta[[pname]]$out_dir,
                   paste0("TH_", yr, "_", sprintf("%02d", mo), ".fst"))
    file.exists(f) && file.size(f) > min_cache_size
  }))
  
  if (all_cached) {
    message(sprintf("[%d/%d] %d-%02d : all polygons cached, skipping.",
                    iz, nrow(dt_zips), yr, mo))
    next
  }
  
  message(sprintf("[%d/%d] %d-%02d : unzipping...",
                  iz, nrow(dt_zips), yr, mo))
  
  # Extract monthly archive into a dedicated temporary subdirectory
  tmp_month <- file.path(tmp_dir, paste0(yr, "_", sprintf("%02d", mo)))
  if (!dir.exists(tmp_month)) dir.create(tmp_month, recursive = TRUE)
  
  nc_names <- tryCatch(
    unzip(zpath, list = TRUE)$Name,
    error = function(e) { message("  ERROR listing ZIP: ", conditionMessage(e)); character(0) }
  )
  
  if (length(nc_names) == 0) {
    message("  Skipping — empty or corrupt ZIP.")
    unlink(tmp_month, recursive = TRUE)
    next
  }
  
  tryCatch(
    unzip(zpath, files = nc_names, exdir = tmp_month, overwrite = TRUE),
    error = function(e) message("  ERROR unzipping: ", conditionMessage(e))
  )
  
  nc_files <- file.path(tmp_month, nc_names)
  nc_files <- nc_files[file.exists(nc_files)]
  
  if (length(nc_files) == 0) {
    message("  No .nc files found after unzip.")
    unlink(tmp_month, recursive = TRUE)
    next
  }
  
  message(sprintf("  %d daily files | processing all polygons in parallel...",
                  length(nc_files)))
  
  # Only process polygons whose cache file is missing or invalid this month
  poly_todo <- names(poly_meta)[sapply(names(poly_meta), function(pname) {
    f <- file.path(poly_meta[[pname]]$out_dir,
                   paste0("TH_", yr, "_", sprintf("%02d", mo), ".fst"))
    !file.exists(f) || file.size(f) <= min_cache_size
  })]
  
  poly_meta_todo <- poly_meta[poly_todo]
  
  # Dispatch daily files to parallel workers; each returns a named list
  # (polygon -> data.table) for that day
  daily_list <- future_lapply(nc_files, function(f_nc) {
    process_day(f_nc, poly_meta_todo)
  }, future.seed = TRUE)
  
  # Reassemble daily results by polygon and write one FST cache per polygon
  for (pname in poly_todo) {
    
    pm      <- poly_meta[[pname]]
    f_cache <- file.path(pm$out_dir,
                         paste0("TH_", yr, "_", sprintf("%02d", mo), ".fst"))
    
    poly_days <- rbindlist(
      lapply(daily_list, function(day_res) {
        if (is.null(day_res) || is.null(day_res[[pname]])) return(NULL)
        day_res[[pname]]
      }),
      fill = TRUE
    )
    
    if (nrow(poly_days) == 0) {
      message(sprintf("  [%s] No valid data for %d-%02d.", pname, yr, mo))
      next
    }
    
    # Restore original FID type (integer or character) as in the source shapefile
    if (!pm$fid_is_char) {
      poly_days[, FID := suppressWarnings(as.integer(FID))]
    }
    
    setorder(poly_days, date, FID)
    write_fst(poly_days, f_cache, compress = 50)
    message(sprintf("  [%s] %d rows saved (%d days x %d FIDs).",
                    pname,
                    nrow(poly_days),
                    uniqueN(poly_days$date),
                    uniqueN(poly_days$FID)))
  }
  
  # Remove extracted daily files; original monthly archives are always kept
  unlink(tmp_month, recursive = TRUE)
  gc()
  
  message(sprintf("[%d/%d] %d-%02d done.", iz, nrow(dt_zips), yr, mo))
}

plan(sequential)

